CREATE DATABASE IF NOT EXISTS bukutamu_man CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bukutamu_man;
CREATE TABLE IF NOT EXISTS admin(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS tamu(id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,asal VARCHAR(150) NOT NULL,hp VARCHAR(25),keperluan VARCHAR(100) NOT NULL,temu VARCHAR(100),catatan TEXT,dibuat DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS survei(id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100),layanan VARCHAR(100) NOT NULL,u1 TINYINT NOT NULL,u2 TINYINT NOT NULL,u3 TINYINT NOT NULL,u4 TINYINT NOT NULL,u5 TINYINT NOT NULL,u6 TINYINT NOT NULL,saran TEXT,dibuat DATETIME DEFAULT CURRENT_TIMESTAMP);
